/**
 * A Tax Threshold Status is where the environment's consumer (B2C) paid
 * sales stand against one jurisdiction's registration threshold for digital
 * services (docs/services/money/web-payments.md, "Tax registration
 * thresholds"). It is computed on read from the sales Money recorded and the
 * threshold table; nothing about it is written by a caller.
 */
export interface TaxThresholdStatus {
	/**
	 * `orgs/{org}/projects/{project}/envs/{env}/tax_threshold_statuses/{threshold}`,
	 * the threshold's id (`au-gst`, `us-tx`).
	 */
	name?: string
	/** The threshold's id, as in `name`. */
	readonly uid?: string
	/** Resource metadata; not set for a computed view. */
	meta?: common.ResourceMeta
	/** The jurisdiction's country, upper-case ISO 3166-1 alpha-2. */
	readonly regionCode?: string
	/** The jurisdiction's subdivision (a US state, `TX`); empty for a country. */
	readonly subdivisionCode?: string
	/** The tax the threshold registers for, for example `GST`. */
	readonly taxName?: string
	/** The threshold's currency, upper-case ISO 4217. */
	readonly currencyCode?: string
	/**
	 * The amount that triggers registration, integer minor units of
	 * `currency_code`; "0" when the threshold is a transaction count only.
	 */
	readonly thresholdAmount?: string
	/** The transaction count that triggers registration; 0 when none. */
	readonly thresholdTransactionCount?: string
	/** `rolling_12_months`, `calendar_year`, or `prior_or_current_calendar_year`. */
	readonly windowKind?: string
	/** The start (inclusive) of the window the figures below cover. */
	readonly windowStartTime?: string
	/** The end of the window (the moment of the read for a rolling window). */
	readonly windowEndTime?: string
	/**
	 * The consumer paid sales in the window, net of tax, in `currency_code`
	 * minor units. Business sales (a tax id was given) are excluded.
	 */
	readonly salesAmount?: string
	/** The number of those sales. */
	readonly salesTransactionCount?: string
	/**
	 * How close the sales are to the threshold, in whole percent (the higher of
	 * the amount and the count); it can exceed 100.
	 */
	readonly percent?: number
	/**
	 * The highest alert level (70, 90, 100) already sent for this window; 0 if
	 * none.
	 */
	readonly alertedPercent?: number
	/**
	 * Currencies of sales that could not be converted into `currency_code`
	 * (no rate in the rate table) and so are not counted in `sales_amount`.
	 */
	readonly unconvertedCurrencyCodes?: string[]
	/** The authority page the threshold comes from. */
	readonly sourceUrl?: string
	/** When the threshold row took effect. */
	readonly effectiveTime?: string
}

