/**
 * MoneyService is Sylphx Money's customer payments: an app sells to its own
 * users through the stores and processors Money integrates once, and asks one
 * question on its request path, "does this subject have this feature"
 * (docs/services/money/customer-payments.md).
 *
 * Namespace of Sylphx Money on `Sylphx`.
 */
export class MoneyApi {
	/** The `price_catalogs` collection. */
	readonly priceCatalogs: PriceCatalogsCollection
	/** The `checkout_policies` collection. */
	readonly checkoutPolicies: CheckoutPoliciesCollection
	/** The `store_connections` collection. */
	readonly storeConnections: StoreConnectionsCollection
	/** The `store_purchases` collection. */
	readonly storePurchases: StorePurchasesCollection
	/** The `customer_subscriptions` collection. */
	readonly customerSubscriptions: CustomerSubscriptionsCollection
	/** The `entitlement_grants` collection. */
	readonly entitlementGrants: EntitlementGrantsCollection
	/** The `merchant_accounts` collection. */
	readonly merchantAccounts: MerchantAccountsCollection
	/** The `checkout_sessions` collection. */
	readonly checkoutSessions: CheckoutSessionsCollection
	/** The `tax_threshold_statuses` collection. */
	readonly taxThresholdStatuses: TaxThresholdStatusesCollection
	/** The `portal_sessions` collection. */
	readonly portalSessions: PortalSessionsCollection
	/** The `licence_keys` collection. */
	readonly licenceKeys: LicenceKeysCollection
	/** The `licence_tokens` collection. */
	readonly licenceTokens: LicenceTokensCollection
	/** The `usage_settings` collection. */
	readonly usageSettings: UsageSettingsCollection
	/** The `usage_tiers` collection. */
	readonly usageTiers: UsageTiersCollection
	/** The `usage_reservations` collection. */
	readonly usageReservations: UsageReservationsCollection
	/** The `usage_events` collection. */
	readonly usageEvents: UsageEventsCollection
	/** The `credit_grants` collection. */
	readonly creditGrants: CreditGrantsCollection
	/** The `usage_invoices` collection. */
	readonly usageInvoices: UsageInvoicesCollection
	/** The `usage_meters` collection. */
	readonly usageMeters: UsageMetersCollection
	/** The `usage_meter_prices` collection. */
	readonly usageMeterPrices: UsageMeterPricesCollection

	constructor(client: runtime.Client) {
		this.priceCatalogs = new PriceCatalogsCollection(client)
		this.checkoutPolicies = new CheckoutPoliciesCollection(client)
		this.storeConnections = new StoreConnectionsCollection(client)
		this.storePurchases = new StorePurchasesCollection(client)
		this.customerSubscriptions = new CustomerSubscriptionsCollection(client)
		this.entitlementGrants = new EntitlementGrantsCollection(client)
		this.merchantAccounts = new MerchantAccountsCollection(client)
		this.checkoutSessions = new CheckoutSessionsCollection(client)
		this.taxThresholdStatuses = new TaxThresholdStatusesCollection(client)
		this.portalSessions = new PortalSessionsCollection(client)
		this.licenceKeys = new LicenceKeysCollection(client)
		this.licenceTokens = new LicenceTokensCollection(client)
		this.usageSettings = new UsageSettingsCollection(client)
		this.usageTiers = new UsageTiersCollection(client)
		this.usageReservations = new UsageReservationsCollection(client)
		this.usageEvents = new UsageEventsCollection(client)
		this.creditGrants = new CreditGrantsCollection(client)
		this.usageInvoices = new UsageInvoicesCollection(client)
		this.usageMeters = new UsageMetersCollection(client)
		this.usageMeterPrices = new UsageMeterPricesCollection(client)
	}
}

/** `price_catalogs` of Sylphx Money: Resource type `money.sylphx.com/PriceCatalog`. */
export class PriceCatalogsCollection {
	private readonly client: runtime.Client

	constructor(client: runtime.Client) {
		this.client = client
	}

	/**
	 * Gets the environment's catalog.
	 *
	 * `GET /v1/{name=orgs/*\/projects/*\/envs/*\/price_catalogs/*}` · permission `billing:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`.
	 */
	async get(request: GetCatalogRequest): Promise<Catalog> {
		return this.client.call<Catalog>({
			method: 'GET',
			path: `/v1/${runtime.pathParam(request.name, 'orgs/*/projects/*/envs/*/price_catalogs/*', 'name')}`,
			responseType: 'sylphx.money.v1.Catalog',
			mutation: false,
		})
	}

	/**
	 * Updates the environment's catalog: its features and products, whole.
	 *
	 * `PATCH /v1/{catalog.name=orgs/*\/projects/*\/envs/*\/price_catalogs/*}` · permission `billing:write` · effect `write`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `UNKNOWN_FIELD`, `INVALID_FIELD`, `ETAG_MISMATCH`, `IDEMPOTENCY_KEY_REUSED`, `IDEMPOTENCY_IN_PROGRESS`.
	 */
	async update(request: UpdateCatalogRequest): Promise<Catalog> {
		return this.client.call<Catalog>({
			method: 'PATCH',
			path: `/v1/${runtime.pathParam(request.catalog?.name, 'orgs/*/projects/*/envs/*/price_catalogs/*', 'catalog.name')}`,
			query: { update_mask: request.updateMask, allow_missing: request.allowMissing, validate_only: request.validateOnly },
			body: request.catalog ?? {},
			bodyType: 'sylphx.money.v1.Catalog',
			responseType: 'sylphx.money.v1.Catalog',
			mutation: true,
		})
	}

	/**
	 * Pushes the catalog to the merchant account's processor now: products and
	 * prices by lookup key; an amount change makes a new price.
	 *
	 * `POST /v1/{name=orgs/*\/projects/*\/envs/*\/price_catalogs/*}:sync` · permission `billing:write` · effect `write`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`, `INVALID_STATE`, `UNAVAILABLE`.
	 */
	async sync(request: SyncCatalogRequest): Promise<Catalog> {
		return this.client.call<Catalog>({
			method: 'POST',
			path: `/v1/${runtime.pathParam(request.name, 'orgs/*/projects/*/envs/*/price_catalogs/*', 'name')}:sync`,
			body: runtime.omit(request, ['name']),
			bodyType: 'sylphx.money.v1.SyncCatalogRequest',
			responseType: 'sylphx.money.v1.Catalog',
			mutation: true,
		})
	}
}

