/** `store_connections` of Sylphx Money: Resource type `money.sylphx.com/StoreConnection`. */
export class StoreConnectionsCollection {
	private readonly client: runtime.Client

	constructor(client: runtime.Client) {
		this.client = client
	}

	/**
	 * Gets a store connection.
	 *
	 * `GET /v1/{name=orgs/*\/projects/*\/envs/*\/store_connections/*}` · permission `billing:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`.
	 */
	async get(request: GetStoreConnectionRequest): Promise<StoreConnection> {
		return this.client.call<StoreConnection>({
			method: 'GET',
			path: `/v1/${runtime.pathParam(request.name, 'orgs/*/projects/*/envs/*/store_connections/*', 'name')}`,
			responseType: 'sylphx.money.v1.StoreConnection',
			mutation: false,
		})
	}

	/**
	 * Lists store connections.
	 *
	 * `GET /v1/{parent=orgs/*\/projects/*\/envs/*}/store_connections` · permission `billing:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `INVALID_FIELD`, `PAGE_TOKEN_MISMATCH`.
	 */
	async list(request: ListStoreConnectionsRequest): Promise<ListStoreConnectionsResponse> {
		return this.client.call<ListStoreConnectionsResponse>({
			method: 'GET',
			path: `/v1/${runtime.pathParam(request.parent, 'orgs/*/projects/*/envs/*', 'parent')}/store_connections`,
			query: { page_size: request.pageSize, page_token: request.pageToken, filter: request.filter },
			responseType: 'sylphx.money.v1.ListStoreConnectionsResponse',
			mutation: false,
		})
	}

	/** Every item of every page of `list`. */
	async *listAll(request: ListStoreConnectionsRequest): AsyncGenerator<StoreConnection> {
		let next: ListStoreConnectionsRequest = request
		for (;;) {
			const page = await this.list(next)
			yield* page.storeConnections ?? []
			if (page.nextPageToken === undefined || page.nextPageToken === '') return
			next = { ...request, pageToken: page.nextPageToken }
		}
	}

	/**
	 * Creates a store connection; its credential is sealed and never returned.
	 *
	 * `POST /v1/{parent=orgs/*\/projects/*\/envs/*}/store_connections` · permission `billing:write` · effect `write`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `UNKNOWN_FIELD`, `INVALID_FIELD`, `RESOURCE_ALREADY_EXISTS`, `IDEMPOTENCY_KEY_REUSED`, `IDEMPOTENCY_IN_PROGRESS`.
	 */
	async create(request: CreateStoreConnectionRequest): Promise<StoreConnection> {
		return this.client.call<StoreConnection>({
			method: 'POST',
			path: `/v1/${runtime.pathParam(request.parent, 'orgs/*/projects/*/envs/*', 'parent')}/store_connections`,
			query: { store_connection_id: request.storeConnectionId, validate_only: request.validateOnly },
			body: request.storeConnection ?? {},
			bodyType: 'sylphx.money.v1.StoreConnection',
			responseType: 'sylphx.money.v1.StoreConnection',
			mutation: true,
		})
	}

	/**
	 * Updates a store connection; a new credential replaces the stored one.
	 *
	 * `PATCH /v1/{store_connection.name=orgs/*\/projects/*\/envs/*\/store_connections/*}` · permission `billing:write` · effect `write`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`, `UNKNOWN_FIELD`, `INVALID_FIELD`, `ETAG_MISMATCH`, `IDEMPOTENCY_KEY_REUSED`, `IDEMPOTENCY_IN_PROGRESS`.
	 */
	async update(request: UpdateStoreConnectionRequest): Promise<StoreConnection> {
		return this.client.call<StoreConnection>({
			method: 'PATCH',
			path: `/v1/${runtime.pathParam(request.storeConnection?.name, 'orgs/*/projects/*/envs/*/store_connections/*', 'store_connection.name')}`,
			query: { update_mask: request.updateMask, allow_missing: request.allowMissing, validate_only: request.validateOnly },
			body: request.storeConnection ?? {},
			bodyType: 'sylphx.money.v1.StoreConnection',
			responseType: 'sylphx.money.v1.StoreConnection',
			mutation: true,
		})
	}

	/**
	 * Deletes a store connection and its sealed credential.
	 *
	 * `DELETE /v1/{name=orgs/*\/projects/*\/envs/*\/store_connections/*}` · permission `billing:write` · effect `destructive`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`, `ETAG_MISMATCH`, `IDEMPOTENCY_KEY_REUSED`, `IDEMPOTENCY_IN_PROGRESS`.
	 */
	async delete(request: DeleteStoreConnectionRequest): Promise<Record<string, never>> {
		return this.client.call<Record<string, never>>({
			method: 'DELETE',
			path: `/v1/${runtime.pathParam(request.name, 'orgs/*/projects/*/envs/*/store_connections/*', 'name')}`,
			query: { etag: request.etag },
			mutation: true,
		})
	}
}

